"""[bf16 variant] AdaptiveAvgMaxPool2d (pool_type='avg', output_size=1): global average pooling over H, W."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'AdaptiveAvgMaxPool2d_13347',
    'batch': 16,
    'channels': 256,
    'height': 128,
    'width': 128,
    'output_size': 1,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width']),
        dtype,
    )
    return (x,)


def workload(x):
    # AdaptiveAvgPool2d(1) on NCHW is a mean over the spatial axes, kept as 1x1.
    return jnp.mean(x, axis=(2, 3), keepdims=True)

"""[bf16 variant] AlphaChooser: clamp(1 + sigmoid(pre_alpha), 1.01, 2)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'AlphaChooser_16276',
    'head_count': 33554432,
    'alpha_min': 1.01,
    'alpha_max': 2.0,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    # Unscaled normal to match torch.randn init, so the min clamp is exercised.
    pre_alpha = jax.random.normal(key, (CONFIG['head_count'],), dtype)
    return (pre_alpha,)


def workload(pre_alpha):
    alpha = 1 + jax.nn.sigmoid(pre_alpha)
    return jnp.clip(alpha, CONFIG['alpha_min'], CONFIG['alpha_max'])

